package com.northstar.crm.ui;

import com.northstar.crm.domain.DomainTypes.Role;import com.northstar.crm.security.ActorResolver;import com.northstar.crm.service.*;import com.vaadin.flow.component.*;import com.vaadin.flow.component.applayout.*;import com.vaadin.flow.component.avatar.Avatar;import com.vaadin.flow.component.button.*;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.icon.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.router.*;import com.vaadin.flow.spring.security.AuthenticationContext;import java.util.*;
public class MainLayout extends AppLayout {
 private final ActorResolver actors;private final AuthenticationContext authentication;private final NotificationService notifications;private final VerticalLayout nav=new VerticalLayout();
 public MainLayout(ActorResolver actors,AuthenticationContext authentication,NotificationService notifications,AssetVersionService assets){this.actors=actors;this.authentication=authentication;this.notifications=notifications;setPrimarySection(Section.DRAWER);getElement().setAttribute("data-asset-version",assets.cacheBustingSuffix());build();}
 private void build(){var user=actors.current();var brandName=new Span("Northstar");brandName.addClassName("brand-name");var brand=new HorizontalLayout(new Div("N"),new VerticalLayout(brandName,new Span("Customer operations")));brand.addClassName("brand");brand.setAlignItems(FlexComponent.Alignment.CENTER);nav.setPadding(false);nav.setSpacing(false);nav.addClassName("nav");addLink("Overview",DashboardView.class,VaadinIcon.DASHBOARD);addLink("Organizations",OrganizationsView.class,VaadinIcon.OFFICE);addLink("Escalations",EscalationsView.class,VaadinIcon.LIFEBUOY);if(user.getRole()!=Role.CUSTOMER_CONTACT)addLink("Reports & transfer",ImportExportView.class,VaadinIcon.CHART);if(user.getRole()==Role.PLATFORM_ADMIN){addLink("People & access",AdminUsersView.class,VaadinIcon.USERS);addLink("Audit ledger",AuditView.class,VaadinIcon.BOOK);}var spacer=new Div();spacer.getStyle().set("flex-grow","1");var profile=new RouterLink("Profile",ProfileView.class);profile.addClassName("profile-link");var drawer=new VerticalLayout(brand,nav,spacer,profile);drawer.addClassName("drawer");drawer.setSizeFull();addToDrawer(drawer);
  var menu=new Button(VaadinIcon.MENU.create(),e->setDrawerOpened(!isDrawerOpened()));menu.addThemeVariants(ButtonVariant.LUMO_TERTIARY_INLINE);menu.setAriaLabel("Toggle navigation");var avatar=new Avatar(user.getDisplayName());avatar.setAbbreviation(initials(user.getDisplayName()));var identityName=new Span(user.getDisplayName());identityName.addClassName("identity-name");var identity=new VerticalLayout(identityName,new Span(UiKit.human(user.getRole())));identity.setPadding(false);identity.setSpacing(false);var alerts=new RouterLink(notifications.unread()+"",NotificationsView.class);alerts.add(VaadinIcon.BELL.create());alerts.addClassName("alert-link");alerts.getElement().setAttribute("aria-label",notifications.unread()+" unread notifications");var logout=new Button("Sign out",VaadinIcon.SIGN_OUT.create(),e->authentication.logout());logout.addThemeVariants(ButtonVariant.LUMO_TERTIARY);var header=new HorizontalLayout(menu,new H2("Customer Operations"),new Div(),alerts,avatar,identity,logout);header.addClassName("topbar");header.expand(header.getComponentAt(2));header.setAlignItems(FlexComponent.Alignment.CENTER);header.setWidthFull();addToNavbar(header);}
 private void addLink(String label,Class<? extends Component> view,VaadinIcon icon){var link=new RouterLink();link.add(icon.create(),new Span(label));link.setRoute(view);nav.add(link);}
 private String initials(String value){return Arrays.stream(value.split(" ")).limit(2).map(s->s.substring(0,1)).reduce("",String::concat).toUpperCase();}
}
